-- Athena saved query (Product_B2C_Intl)
-- ID: 4aba18ae-493c-4620-8147-07ac0cd21571
-- Name: Top 500 Routes Student x Primo - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

SELECT source_location_id, destination_location_id, (source_location ||'-'|| destination_location) AS route, '' route_category, COUNT(DISTINCT tin) txn_count, COUNT(DISTINCT CASE WHEN hft = 2 THEN tin END) AS primo_txn_count, COUNT(DISTINCT CASE WHEN travellers_age[1] < 24 THEN tin END) AS student_txn_count, COUNT(DISTINCT CASE WHEN travellers_age[1] < 24 AND hft = 2 THEN tin END) AS student_primo_txn_count, COUNT(DISTINCT CASE WHEN seat_count >= 3 THEN tin END) AS all_3plusseat_txn_count, COUNT(DISTINCT CASE WHEN seat_count >= 3 AND hft = 2 THEN tin END) AS primo_3plusseat_txn_count, COUNT(DISTINCT CASE WHEN travellers_age[1] < 24 AND seat_count >= 3 THEN tin END) AS student_3plusseat_txn_count, COUNT(DISTINCT CASE WHEN travellers_age[1] < 24 AND seat_count >= 3 AND hft = 2 THEN tin END) AS student_primo_3plusseat_txn_count, COUNT(DISTINCT CAST(operator_id AS VARCHAR) ||'-'|| service_id) AS txt_services, COUNT(DISTINCT CASE WHEN hft = 2 THEN CAST(operator_id AS VARCHAR) ||'-'|| service_id END) AS txt_primo_services, COUNT(DISTINCT CASE WHEN travellers_age[1] < 24 THEN CAST(operator_id AS VARCHAR) ||'-'|| service_id END) AS student_txt_services, COUNT(DISTINCT CASE WHEN travellers_age[1] < 24 AND hft = 2 THEN CAST(operator_id AS VARCHAR) ||'-'|| service_id END) AS student_txt_primo_services FROM transaction.bus_ticket_events AS bte -- LEFT JOIN "lis"."config_locations" src ON bte.source_location_id = src.id -- LEFT JOIN "lis"."config_locations" dest ON bte.destination_location_id = dest.id WHERE 1=1 AND bte.time_of_event >= CAST('2026-04-01 00:00:00' AS TIMESTAMP) AND bte.time_of_event < CAST('2026-07-01 00:00:00' AS TIMESTAMP) AND bte.event_type = 101 AND bte.event_class = 2 AND tin IS NOT NULL AND bte.country_code = 'IND' GROUP BY 1, 2, 3, 4 ORDER BY 5 DESC LIMIT 500
